def can_reach(x, y, c, d):
    while c >= x and d >= y:
        if c == x and d == y:
            return True
        if c == d:
            return False
        if c > d:
            if d == y:
                return (c - x) % d == 0
            c %= d
        else:
            if c == x:
                return (d - y) % c == 0
            d %= c
    return False
